  if coalesce(length(name_value)'); d:=replace(d,'or coalesce(length(email_value),0) not between 3 and 254 or email_value !~','or ((kind<>''visitor'' or email_value<>'''') and (coalesce(length(email_value),0) not between 3 and 254 or email_value !~'); d:=replace(d,'$'' then raise exception ''Enter your name, company and valid email''','$'')) then raise exception ''Enter your name and company, and a valid email if provided'''); d:=replace(d,'and lower(actor_email)=email_value','and ((email_value<>'''' and lower(actor_email)=email_value) or (email_value='''' and lower(actor_name)=lower(name_value) and lower(actor_company)=lower(company_value)))'); execute d; end $$;
